insert into menu_items (id, category_id, name_uk, description_uk, price, original_price, promo_label, weight, storage_note, badge, freezable, min_order_override, photo_url, sort_order) values
  ('7e4a7349-8d0b-4d41-8d61-7269e3ed257a', 'c5393b94-8afc-4c79-972b-65e09be734df', 'Наполеон чорничний', 'Наполеон з чорничним кремом на основі заварного крему з вершками та чорницею, декорований лохиною.', 1250, 1500, 'Товар тижня · -15%', '1,7 кг', 'Термін придатності: 4 доби.', null, false, null, '/menu/9ba679784787.png', 0),
  ('032a1740-851e-4411-b934-5388b75b45f2', 'c5393b94-8afc-4c79-972b-65e09be734df', 'Тарт з малиною', 'Пісочна основа, фісташкова начинка та свіжа малина.', 1050, null, null, '1,33 кг', 'Термін придатності: 3 доби.', null, false, null, '/menu/6dc13a9303fb.jpg', 1),
  ('f72e5ba8-c91e-4d55-b351-51b9e904654f', 'c5393b94-8afc-4c79-972b-65e09be734df', 'Тарт чорничний з мʼятою', 'Пісочна основа, мʼятний крем на основі білого шоколаду, крем з чорницею та вершками, декорований лохиною.', 980, null, null, '1,13 кг', 'Термін придатності: 3 доби.', null, false, null, '/menu/bc361f36f6b9.png', 2),
  ('6d7d64d7-5217-4262-ad3b-6d8e7346970c', 'c5393b94-8afc-4c79-972b-65e09be734df', 'Торт Тропік', 'Вершкові бісквіти, крем манго, конфі маракуя зі шматочками манго, декорований вершками і кюлі маракуя.', 1300, null, null, '1,68 кг', 'Термін придатності: 4 доби.', null, false, null, '/menu/a4745283bbc8.png', 3),
  ('3fc90169-4c7b-476b-a651-32cd9f76dc8f', '7b0d3daa-8f69-480a-bc58-1d7eaa8ae9f4', 'Ягідний йогурт', 'Круглий круасан з листкового тіста. Начинка: йогуртово-ягідний крем. Прикрашений кольоровою глазурʼю і сезонними ягодами.', 125, null, null, '190 г', null, null, false, null, '/menu/8ffd1e572272.png', 0),
  ('913b106c-197f-425e-bf46-86785f346bf1', '7b0d3daa-8f69-480a-bc58-1d7eaa8ae9f4', 'Фісташка-малина', 'Круглий круасан з листкового тіста. Начинка: вершково-фісташковий крем та малинове кюлі. Прикрашений кольоровою глазурʼю, сезонними ягодами та подрібненою фісташкою.', 133, null, null, '180 г', null, null, false, null, '/menu/a1b87a3e6614.png', 1),
  ('47d425ba-cf20-414e-8315-95b551211d5f', '7b0d3daa-8f69-480a-bc58-1d7eaa8ae9f4', 'Вибухова карамель', 'Круглий круасан з листкового тіста. Начинка: крем із солоною карамеллю. Прикрашений карамеллю і солодким попкорном.', 125, null, null, '170 г', null, null, false, null, '/menu/2948dfc99f15.png', 2),
  ('dcfa301d-e78b-4ebd-b7a2-60a1eed9298c', '7b0d3daa-8f69-480a-bc58-1d7eaa8ae9f4', 'Манго-маракуя', 'Круглий круасан з листкового тіста. Начинка: крем зі смаком манго-маракуя. Прикрашений кольоровою глазурʼю, сушеним манго і шоколадною крихтою.', 125, null, null, '180 г', null, null, false, null, '/menu/a4bb890aa68b.png', 3),
  ('7d074213-6094-4a24-b43f-f1e86c1e18fc', '7b0d3daa-8f69-480a-bc58-1d7eaa8ae9f4', 'Шоколадний цитрус', 'Круглий круасан з листкового тіста. Начинка: вершково-шоколадний крем з апельсиново-лимонним курдом. Прикрашений шоколадною глазурʼю і апельсином.', 125, null, null, '190 г', null, null, false, null, '/menu/5f4fd5e6f0b5.png', 4),
  ('3049fc0a-0d31-4b86-9039-0eb47967d55d', '7b0d3daa-8f69-480a-bc58-1d7eaa8ae9f4', 'Полуниця', 'Круасан-рол з вершковим кремом на основі білого шоколаду та полуничне конфі зі свіжою полуницею. Декорований сублімованими ягодами.', 125, null, null, '190 г', null, 'ОНОВЛЕННЯ ДЕКОРУ', false, null, '/menu/ef9e86424ece.png', 5),
  ('43008e0e-89f8-488f-8cc7-a3dc70edbf2f', 'a408eca8-fc77-4666-b451-cb115d84d3d8', 'Шоколадний', 'Листкове тісто з вершковим маслом. Начинка: шоколадно-фундучна.', 73, null, null, '136 г', null, null, false, null, '/menu/9bfef34b04bd.png', 0),
  ('21d1d7c2-eae3-477a-b91a-7300bb4332e4', 'a408eca8-fc77-4666-b451-cb115d84d3d8', 'Вишневий', 'Листкове тісто з вершковим маслом. Начинка: цілі шматочки натуральної вишні.', 69, null, null, '136 г', null, null, false, null, '/menu/8e466b949d4c.png', 1),
  ('eb3b22b5-cc45-422e-af79-8926824e198d', 'a408eca8-fc77-4666-b451-cb115d84d3d8', 'Мигдалевий', 'Листкове тісто з вершковим маслом. Начинка: франжипан, в якому багато мигдального борошна з нотками апельсину та коньяку. Прикрашений мигдальними пластівцями.', 83, null, null, '145 г', null, null, false, null, '/menu/b363238bb774.png', 2),
  ('b451e6ff-21b9-4d40-83b3-115070bc9d22', 'a408eca8-fc77-4666-b451-cb115d84d3d8', 'Класичний', 'Ніжне і ароматне листкове тісто. Без начинки.', 55, null, null, '95 г', null, null, false, null, null, 3),
  ('7dbee4da-be64-4b61-af00-1b4ff5316476', 'a408eca8-fc77-4666-b451-cb115d84d3d8', 'Лимонний', 'Ніжне листкове тісто. Начинка: лимонний крем з кислинкою. Прикрашений італійською меренгою.', 99, null, null, '160 г', null, null, false, null, '/menu/4aa98620d70e.png', 4),
  ('0bb37c6f-d707-4287-8adf-bff505ec7508', 'a408eca8-fc77-4666-b451-cb115d84d3d8', 'Фісташковий', 'Листкове тісто з вершковим маслом. Начинка: фісташковий крем власного виробництва з фісташковою пастою.', 112, null, null, '165 г', null, null, false, null, '/menu/e80614c76d97.png', 5),
  ('62c69b97-0820-4483-b298-2e663377426a', 'a408eca8-fc77-4666-b451-cb115d84d3d8', 'Кокосовий', 'Листкове тісто. Начинка: на основі білого шоколаду та кокосового борошна. Прикрашений глазурʼю та кокосовою стружкою.', 99, null, null, '150 г', null, null, false, null, '/menu/57a312a67550.png', 6),
  ('5f28283c-c913-4e42-a040-a53b3e1ca168', 'a408eca8-fc77-4666-b451-cb115d84d3d8', 'Йогуртовий', 'Ніжне листкове тісто. Начинка: йогуртова та чорнично-смородинова. Прикрашений сублімованою малиною.', 99, null, null, '170 г', null, null, false, null, '/menu/cc2c5dd265bf.png', 7),
  ('b92fc0a5-e274-4ca9-9c0f-294b5468dbee', 'a408eca8-fc77-4666-b451-cb115d84d3d8', 'Равлик вишневий', 'Равлик з листкового тіста з корицею та вишневим кюлі. Вкритий вишневим соусом.', 37, null, null, '125 г', null, null, false, 4, '/menu/96f0229bd278.png', 8),
  ('fc56f744-72a4-4ac2-954d-1aa9cb1cc7c3', '89cea3b8-c64e-4d5f-a44f-5dfada37df75', 'Чізкейк Нью-Йорк з солоною карамеллю', 'Класичний чізкейк з ніжним вершковим сиром. Вкритий тягучою солоною карамеллю власного виробництва. Прикрашений сезонними ягодами та мигдальними пластівцями. К-ть шматочків — 10 шт.', 990, null, null, '1,6 кг', null, 'ОНОВЛЕННЯ ДЕКОРУ', false, null, '/menu/cfed1bf3c967.png', 0),
  ('4e9b1c93-d816-49d6-8d33-aa58391a6298', '89cea3b8-c64e-4d5f-a44f-5dfada37df75', 'Чізкейк Нью-Йорк з солоною карамеллю (шматочок)', 'Шматочок чізкейка Нью-Йорк з солоною карамеллю та сезонними ягодами.', 99, null, null, '160 г', null, null, false, null, '/menu/cfed1bf3c967.png', 1),
  ('70edebb4-b611-44d3-b285-47f8121145bb', '89cea3b8-c64e-4d5f-a44f-5dfada37df75', 'Чізкейк Нью-Йорк', 'Класичний чізкейк. Основа з пісочного тіста. Зроблений з ніжним вершковим сиром. К-ть шматочків — 10 шт.', 890, null, null, '1,4 кг', null, null, false, null, '/menu/fc49ec3aa801.jpg', 2),
  ('55b56fdf-aebd-415e-91e2-67f136b9734c', '89cea3b8-c64e-4d5f-a44f-5dfada37df75', 'Чізкейк Нью-Йорк (шматочок)', 'Шматочок класичного чізкейка Нью-Йорк.', 89, null, null, '140 г', null, null, false, null, '/menu/fc49ec3aa801.jpg', 3),
  ('30af36a9-035e-4766-878c-136a90f21e0a', 'bb02a48c-564c-455d-beb2-e8145397e07c', 'Манго-полуниця', 'Заварне тісто. Начинка: крем-муслін на основі білого шоколаду, натуральне манго, полуничне кюлі. Прикрашений кольоровою глазурʼю, ніжним кремом і сублімованою полуницею.', 79, null, null, '75 г', null, null, true, null, '/menu/208bfad9389e.png', 0),
  ('c057b3a2-360c-48c2-887b-9920e953b0fd', 'bb02a48c-564c-455d-beb2-e8145397e07c', 'Чорниця-лимон', 'Заварне тісто. Начинка: чорничний крем на основі білого шоколаду та вершків, лимонний курд. Прикрашений лохиною і ніжним кремом.', 82, null, null, '100 г', null, null, true, null, '/menu/4cb79ce76ba7.png', 1),
  ('16168783-84ce-42d1-a5fd-102cc6993154', 'bb02a48c-564c-455d-beb2-e8145397e07c', 'Фісташковий', 'Заварне тісто. Начинка: крем-муслін на основі білого шоколаду, сезонні ягоди. Прикрашений кольоровою глазурʼю та подрібненою фісташкою.', 89, null, null, '70 г', null, null, true, null, '/menu/6cf75c9c9476.jpg', 2),
  ('34a07dc1-5ad6-431f-9f54-59f655106af4', 'bb02a48c-564c-455d-beb2-e8145397e07c', 'Шоколадний', 'Заварне тісто. Начинка: крем-муслін на основі білого шоколаду з додаванням чорного шоколаду. Прикрашений кольоровою глазурʼю і ніжним шоколадним кремом.', 79, null, null, '80 г', null, null, true, null, '/menu/57ac89055183.jpg', 3),
  ('78a11e99-ca1d-4c76-8165-b5490ec6d554', 'bb02a48c-564c-455d-beb2-e8145397e07c', 'Солона карамель', 'Заварне тісто. Начинка: крем-муслін на основі білого шоколаду, солона карамель. Прикрашений кольоровою глазурʼю, горіховою крихтою і солодким попкорном.', 79, null, null, '70 г', null, null, true, null, '/menu/375593ca2bea.jpg', 4),
  ('89ddf91a-85ae-4391-ba1d-f86ecb4e4644', 'bb02a48c-564c-455d-beb2-e8145397e07c', 'Малина-мʼята', 'Заварне тісто. Начинка: крем-муслін на основі білого шоколаду, мʼята та малинове кюлі власного виробництва. Прикрашений кольоровою глазурʼю.', 79, null, null, '70 г', null, null, true, null, '/menu/5f6763475649.png', 5),
  ('9f415678-3647-42da-bc5a-23957db1c272', 'bb02a48c-564c-455d-beb2-e8145397e07c', 'Ванільний', 'Заварне тісто. Начинка: крем-муслін на основі білого шоколаду з ваніллю. Прикрашений кольоровою глазурʼю і ніжним кремом.', 79, null, null, '75 г', null, null, true, null, '/menu/0df418d3cfb6.jpg', 6),
  ('772f9823-e293-48da-99eb-c27fac01adb4', 'bb02a48c-564c-455d-beb2-e8145397e07c', 'З полуницею', 'Еклер з подвійною начинкою: ванільним кремом на основі білого шоколаду та полуничним конфі зі свіжою полуницею.', 89, null, null, '100 г', null, null, true, null, '/menu/b59af67e77bf.png', 7),
  ('6b93cc82-6d44-459e-bbbc-736b80e4deb3', '0ae67fb8-0726-4655-97a2-0c934e467cd5', 'Фісташка-малина', 'Фісташкові коржі, малинове кюлі та фісташково-вершковий крем. Декорований фісташкою та сублімованою або свіжою малиною. К-ть шматочків — 12 шт. Шматок — 123 грн.', 1470, null, null, '1,9 кг', null, null, true, null, '/menu/629f78b0ab21.png', 0),
  ('dff007be-ab7e-4822-8ac2-9b5274815efd', '0ae67fb8-0726-4655-97a2-0c934e467cd5', 'Полуниця-карамель', 'Ванільний бісквіт, полуничне кюлі, вершковий крем та карамель власного виробництва. К-ть шматочків — 12 шт. Шматок — 114 грн.', 1370, null, null, '1,7 кг', null, 'ОНОВЛЕННЯ ДЕКОРУ', true, null, '/menu/0aceaf035a93.png', 1),
  ('506a0f73-0a69-4604-9088-affa405e255a', '0ae67fb8-0726-4655-97a2-0c934e467cd5', 'Снікерс', 'Шоколадні коржі, вершково-масляний крем, арахіс та тягуча карамель власного виробництва. К-ть шматочків — 12 шт. Шматок — 115 грн.', 1530, null, null, '2,3 кг', null, null, false, null, '/menu/b7e32be94ab0.png', 2),
  ('54c14aba-857a-4e01-80d5-646c74f28be7', '0ae67fb8-0726-4655-97a2-0c934e467cd5', 'Меренговий торт з сезонними ягодами', 'Коржі меренги з полуничним кремом на крем-сирі та з полуничним кюлі в начинці. Декорований свіжими ягодами на вибір.', 980, null, null, '1,3 кг', null, null, false, null, '/menu/a4745283bbc8.png', 3),
  ('cd2ee98d-984b-441a-a194-08280bdff128', '0ae67fb8-0726-4655-97a2-0c934e467cd5', 'Естерхазі', 'Мигдально-горіхові коржі, масляно-заварний крем зі згущеним молоком. К-ть шматочків — 12 шт. Шматок — 108 грн.', 1300, null, null, '1,75 кг', null, null, true, null, '/menu/2f61916c9009.png', 4),
  ('19017ea7-4914-49f3-95e4-e2270f9eb03f', '0ae67fb8-0726-4655-97a2-0c934e467cd5', 'Полуничний наполеон', 'Класичні коржі, ніжний заварний крем з вершками, полуничне кюлі, декорований сезонними ягодами.', 1250, null, null, '2 кг', null, 'ОНОВЛЕННЯ ДЕКОРУ', false, null, '/menu/9ba679784787.png', 5),
  ('3d2c56bc-2c0f-45bb-9c85-419b3bab4e21', '0ae67fb8-0726-4655-97a2-0c934e467cd5', 'Класичний наполеон', 'Ніжне листкове тісто. Заварний крем на ароматному вершковому маслі. К-ть шматочків — 12 шт. Шматок — 104 грн.', 1200, null, null, '2 кг', null, null, false, null, '/menu/9ba679784787.png', 6),
  ('82d6f198-cb7b-4354-862e-6c964c0ad0f2', '0ae67fb8-0726-4655-97a2-0c934e467cd5', 'Медівник з вишнею', 'Медові коржі, вершковий сметанний крем та вишня. К-ть шматочків — 12 шт. Шматок — 108 грн.', 1250, null, null, '2,2 кг', null, null, false, null, '/menu/f151674c9efa.png', 7),
  ('1ded5757-b605-4b59-b223-6b357ec51897', '0ae67fb8-0726-4655-97a2-0c934e467cd5', 'Бенто тортики', 'Смаки: фісташка-малина, полуниця-карамель, снікерс. Індивідуальний декор.', 680, null, null, '0,5 кг', null, null, false, null, '/menu/63d05230bdb9.png', 8),
  ('ce8feb61-cfdd-402c-8993-f5f71830e56d', '1806b3ae-7810-4f2f-8f7a-1d3ba215faf1', 'Лимонний', 'Тарт на основі пісочного тіста з лимонним курдом та італійською меренгою. К-ть шматочків — 10 шт. Шматок — 73 грн.', 750, null, null, '1,5 кг', null, null, false, null, '/menu/efcdea506b8f.png', 0),
  ('14243136-788e-4670-8776-2440d0165fce', '1806b3ae-7810-4f2f-8f7a-1d3ba215faf1', 'З панакотою та смородиною', 'Пісочна основа, смородинове конфі, панакота та ніжна меренга. Шматок — 95 грн.', 980, null, null, '1,7 кг', null, null, false, null, '/menu/bc361f36f6b9.png', 1),
  ('9dc60241-4d6d-46b8-a792-01a265f82491', '1806b3ae-7810-4f2f-8f7a-1d3ba215faf1', 'З малиною', 'Пісочне тісто з мигдалевим борошном, фісташковий крем та свіжа малина.', 1050, null, null, '1,4 кг', 'Термін придатності: 3 доби.', null, false, null, '/menu/6dc13a9303fb.jpg', 2),
  ('d0727972-0d66-4665-9db0-d808e6863068', '7784dc99-ca86-427f-a111-d2b61899e6c3', 'Міні-тарт малина', 'Пісочний хрумкий міні-тарт зі свіжою малиною та ванільним кремом на основі білого шоколаду.', 71, null, null, '60 г', null, 'ОНОВЛЕННЯ ДЕКОРУ', false, null, '/menu/03dfe9b16565.jpg', 0),
  ('c88856ba-1c67-4b62-9d26-d82664a1df53', '7784dc99-ca86-427f-a111-d2b61899e6c3', 'Міні-тарт лимонний', 'Пісочний хрумкий тарт з лимонним курдом та білково-заварним кремом.', 69, null, null, '60 г', null, null, false, null, '/menu/cc804f4f4c83.png', 1),
  ('1d208b1c-1cac-4d0d-8d14-cddc4679c041', '1bb1e74a-a49d-4d31-b287-7197873addd0', 'Кіш курка-гриби', 'Листкове тісто. Курка та гриби. Сирно-вершкова заливка, велика кількість сиру сулугуні та моцарели. Прикрашений томатами чері.', 790, null, null, '1,2 кг', null, null, true, null, '/menu/ac7604e063fa.jpg', 0),
  ('4ad80d2c-c154-4ff6-8244-a55ae209f5f4', 'af524fe9-b874-4046-a931-6f4351807fc3', 'З баликом', 'Класичний круасан. Крем-сир, балик, сир чедер, огірок, салат.', 110, null, null, '200 г', null, null, false, null, '/menu/7369b8427a8c.png', 0),
  ('01e779b8-8e85-410a-9989-4f928147ec16', 'af524fe9-b874-4046-a931-6f4351807fc3', 'Зерновий з куркою', 'Зерновий круасан. Майонез, курячий рулет, сир чедер, помідор, салат.', 115, null, null, '200 г', null, null, false, null, '/menu/6eef747a2f5e.png', 1),
  ('30cce79c-955f-40e6-be2b-64bac285ed04', 'af524fe9-b874-4046-a931-6f4351807fc3', 'З куркою «Теріякі»', 'Круасан. Майонез, соус теріякі, салат, огірок, запечена курка, імбир, кунжут.', 127, null, null, '220 г', null, null, false, null, '/menu/d90b047ab4bd.png', 2),
  ('76c1e9f2-e361-4739-a40e-37b1923d609c', 'af524fe9-b874-4046-a931-6f4351807fc3', 'З куркою «Цезар»', 'Круасан. Соус цезар, салат айсберг, помідор, запечена курка, яйце варене, сир пармезан.', 137, null, null, '245 г', null, null, false, null, '/menu/0e55502a86c3.png', 3),
  ('b44724f8-f496-4774-af76-73d3c5c63cef', 'af524fe9-b874-4046-a931-6f4351807fc3', 'З телятиною і солоними огірками', 'Круасан. Запечена телятина, солоний огірок, карамелізована цибуля, салат, сир чедер, соус ягідний, соус «американський стиль».', 132, null, null, '210 г', null, null, false, null, '/menu/42c222be1c1c.png', 4),
  ('c288ac49-6b93-4a60-924c-f3ee37ec0e65', 'aedf71a6-8000-494b-b9bb-af892eb756a3', 'Хамон & помідор', 'Хліб гречаний на заквасці власного виробництва, соус гірчично-медовий, хамон, рукола, сир салямі, помідор.', 135, null, null, '245 г', null, null, false, null, '/menu/b5e7fbbdb5c5.jpg', 0),
  ('5ab7f1f0-c5cc-4f69-8de5-5d7935c4fb7b', 'aedf71a6-8000-494b-b9bb-af892eb756a3', 'Телятина & ягідний соус', 'Хліб гречаний на заквасці, телятина запечена рвана власного виробництва, соус ягідний, соус чікфілей фірмовий, сир твердий, карамелізована цибуля, помідор.', 115, null, null, '200 г', null, null, false, null, '/menu/3401a6102bd7.jpg', 1),
  ('4e47710f-f382-42ac-93a2-7b18f4e13e08', 'aedf71a6-8000-494b-b9bb-af892eb756a3', 'Запечена індичка', 'Хліб гречаний на заквасці, індичка печена рвана власного виробництва, рукола, помідор, сир королівський, карамелізована цибуля, соус чікфілей фірмовий.', 110, null, null, '200 г', null, null, false, null, '/menu/646fa96ff10d.jpg', 2),
  ('d71d7f5d-9358-41d1-b4c8-0a29874568fa', 'aedf71a6-8000-494b-b9bb-af892eb756a3', 'Шинка & овочі', 'Хліб гречаний на заквасці, сир гауда, шинка, соус кисло-солодкий, рукола, листя салату, огірок, помідор.', 110, null, null, '200 г', null, null, false, null, '/menu/70ee931a91a3.jpg', 3),
  ('2880f193-7690-4e3d-98a1-aa4b444abed3', 'aedf71a6-8000-494b-b9bb-af892eb756a3', 'Вʼялена яловичина', 'Хліб гречаний на заквасці, яловичина вʼялена, соус мексиканський, кисло-солодкий соус, листя салату, помідор, огірок, сир твердий.', 122, null, null, '200 г', null, null, false, null, '/menu/d6f4f6e54978.jpg', 4),
  ('81078788-54ba-4772-adb9-c39c9cfc1565', '303d7ca6-685c-481a-b7be-785315a6eb3f', '«Картопля» вишня', 'Шоколадний бісквіт з коньяком. У начинці солодка вишня. Глазур на основі білого шоколаду.', 57, null, null, '85 г', null, null, true, null, '/menu/5cd5e493ce25.jpg', 0),
  ('12cfc92c-1dd7-4f88-aa4d-dcab35254111', '303d7ca6-685c-481a-b7be-785315a6eb3f', '«Картопля» фісташка-малина', 'Фісташковий бісквіт з фісташковою пастою і малинове кюлі. Вкрита глазурʼю на основі білого шоколаду.', 65, null, null, '85 г', null, null, true, null, '/menu/bcf0157881e2.png', 1),
  ('2b3b77f3-5834-4211-8a13-16a5f219d573', '303d7ca6-685c-481a-b7be-785315a6eb3f', '«Картопля» карамель', 'Шоколадний бісквіт з молоком, какао та коньяком. У начинці солона карамель власного виробництва.', 52, null, null, '85 г', null, null, true, null, '/menu/372a5389a1f7.png', 2),
  ('02204240-4637-43f0-90cb-9ee4757816b3', '303d7ca6-685c-481a-b7be-785315a6eb3f', '«Картопля» рафаелло', 'Крем з білого шоколаду та мигдаль.', 52, null, null, '85 г', null, null, true, null, '/menu/e84436b854f7.jpg', 3),
  ('0654519b-deff-4405-a079-c19d0ffa9fd8', '61347c7c-1f5a-4ed3-901a-9ffa06ac2b34', 'Десерт Павлова', 'Ніжне безе, крем на основі вершкового сиру та малинове кюлі. Прикрашений сезонними ягодами.', 79, null, null, '85 г', 'Термін зберігання: 3 дні', null, false, 4, '/menu/3d2b7175c467.jpg', 0),
  ('2e744841-40ae-4129-a74d-8ca2539b4e73', '61347c7c-1f5a-4ed3-901a-9ffa06ac2b34', 'Десерт Павлова «Чорниця-лимон»', 'Меренга, чорничний крем та лимонний курд.', 82, null, null, '90 г', 'Термін зберігання: 3 дні', null, false, 4, '/menu/64d16a715483.jpg', 1),
  ('eb87b264-19f1-4e94-a333-11d2953db038', '61347c7c-1f5a-4ed3-901a-9ffa06ac2b34', 'Десерт Павлова «Манго-маракуя»', 'Меренга, крем манго, кюлі з маракуєю.', 82, null, null, '85 г', 'Термін зберігання: 3 дні', null, false, 4, '/menu/fd8fb804054b.jpg', 2),
  ('76170d8d-b286-4841-98f9-ba89ee98ab6f', '61347c7c-1f5a-4ed3-901a-9ffa06ac2b34', 'Трайфл ягоди-фісташка', 'Фісташковий заварний крем, ванільний бісквіт та полуничне кюлі. Декорований свіжими ягодами.', 68, null, null, '115 г', 'Термін зберігання: 4 дні', 'ОНОВЛЕННЯ ДЕКОРУ', false, 5, '/menu/01b76be415fc.jpg', 3),
  ('88fff8f8-1113-4a2d-b0fd-d19c2d3de21a', '61347c7c-1f5a-4ed3-901a-9ffa06ac2b34', 'Трайфл тірамісу', 'Крем тірамісу, печиво савоярді, кава, какао порошок.', 91, null, null, '95 г', 'Термін зберігання: 4 дні', null, false, 5, '/menu/3aa40447dad8.jpg', 4),
  ('12d10481-0488-43d7-a3e9-57d407cf43aa', '61347c7c-1f5a-4ed3-901a-9ffa06ac2b34', 'Шоколадна ковбаска', 'Смак дитинства: насичена шоколадна ковбаса з подрібненими волоськими горіхами та печивом.', 75, null, null, '150 г', 'Термін зберігання: 2 тижні. У морозі — півтора місяці.', null, true, 5, '/menu/82d42bf0ce6d.jpg', 5),
  ('72ce918c-c3ed-4b67-8023-e41dd75fdec7', '61347c7c-1f5a-4ed3-901a-9ffa06ac2b34', 'Трубочки ягідні', 'Хрумке пісочне тісто в поєднанні з ягідно-масляним кремом. Декоровані сублімованою малиною.', 60, null, null, '80 г', 'Термін зберігання: 7 днів', null, false, 10, '/menu/02a959be7616.png', 6),
  ('e0777e26-7521-4aab-9c84-1a32a8f2051f', '61347c7c-1f5a-4ed3-901a-9ffa06ac2b34', 'Трубочки з арахісом і згущеним молоком', 'Десерт, що родом з дитинства. Хрусткі вафлі із начинкою зі згущеного молока, прикрашені подрібненим арахісом.', 58, null, null, '70-75 г', 'Термін зберігання: 7 днів', null, false, 10, '/menu/a470664d0b5b.jpg', 7),
  ('082e9aa9-d87f-4527-a676-c87be25284b2', '61347c7c-1f5a-4ed3-901a-9ffa06ac2b34', 'Солона карамель власного виробництва', 'Тягуча солона карамель власного виробництва.', 690, null, null, '1 кг', null, null, false, 1, '/menu/7eaa155155f9.png', 8),
  ('62ce1686-dd4c-4aea-8e13-9d1da904c81d', '3a11b8e9-e1be-46e7-a29d-3a8428c3bf94', 'Полуниця', 'Бісквітне ніжне та пухке тісто з полуничною начинкою.', 57, null, null, '70 г', null, null, true, null, '/menu/541238ce6923.jpg', 0),
  ('79f55ccd-3fe4-492e-8f12-229127a19736', '3a11b8e9-e1be-46e7-a29d-3a8428c3bf94', 'Лісові ягоди', 'Бісквітне ніжне та пухке тісто з подвійною начинкою з лісових ягід і сирного крему.', 57, null, null, '70 г', null, null, true, null, '/menu/523d2ec84f43.jpg', 1),
  ('acc27e61-44f0-437c-893d-48035f5afc0a', '3a11b8e9-e1be-46e7-a29d-3a8428c3bf94', 'Чорний шоколад', 'Бісквітне ніжне та пухке тісто з шоколадною начинкою.', 57, null, null, '70 г', null, null, true, null, '/menu/2cd61e165c1e.jpg', 2),
  ('b573609b-0987-4323-a674-267400f52151', '3a11b8e9-e1be-46e7-a29d-3a8428c3bf94', 'Солона карамель', 'Бісквітне ніжне та пухке тісто з начинкою з солоної карамелі власного виробництва.', 57, null, null, '70 г', null, null, true, null, '/menu/fa5fc113f794.jpg', 3),
  ('b68b160d-1886-4ccc-a413-5b973c4f97c9', '3a11b8e9-e1be-46e7-a29d-3a8428c3bf94', 'Панна котта', 'Бісквітне ніжне та пухке тісто з подвійною начинкою з малини та сирного крему, прикрашений сублімованою полуницею.', 57, null, null, '70 г', null, null, true, null, '/menu/811b67cfd9f0.jpg', 4),
  ('6f004f11-24e0-4e52-8b98-99989f47c83a', '3a11b8e9-e1be-46e7-a29d-3a8428c3bf94', 'Вишневий', 'Бісквітне ніжне та пухке тісто двох різних кольорів — завдяки натуральному барвнику карміну, зі свіжою вишневою начинкою.', 57, null, null, '70 г', null, null, true, null, '/menu/c47806b909be.jpg', 5),
  ('bcc17863-d79e-4a25-84c6-bdcbeb8de680', '3a11b8e9-e1be-46e7-a29d-3a8428c3bf94', 'Лісовий горіх', 'Шоколадне ніжно-повітряне тісто з кремовою начинкою з лісового горіха.', 59, null, null, '70 г', null, null, true, null, '/menu/03213aed1998.jpg', 6),
  ('0bb90b02-6a8d-4e4d-91b5-249154ea0e1a', '62180cd2-9750-466e-a404-64429dc54a69', 'Шампанське — смородина', 'Білий шоколад lubeka 33%, вершки smietanka 36%, ром, масло 82%, пюре смородини.', 60, null, null, '40-45 г', null, null, false, null, '/menu/746dd1e1ec20.jpg', 0),
  ('b3360290-c128-46cf-8252-3d7b351b5030', '62180cd2-9750-466e-a404-64429dc54a69', 'Бейліз — солона карамель', 'Білий шоколад 33%, вершки 36%, кава, віскі, вершкове масло 82%. Серединка: солона карамель.', 60, null, null, '40-45 г', null, null, false, null, '/menu/e1fc53b2420d.jpg', 1),
  ('c4445c23-106a-4e1f-a620-a7c00911b5f4', '62180cd2-9750-466e-a404-64429dc54a69', 'Дорблю — груша', 'Білий шоколад, вершки, сир дорблю. Серединка: кюлі з груші.', 60, null, null, '40-45 г', null, null, false, null, '/menu/a5a1f04903a2.jpg', 2),
  ('4a63fb11-a8d7-4ae2-8e1f-f10db0a54d96', '62180cd2-9750-466e-a404-64429dc54a69', 'Мохіто — малина', 'Білий шоколад, вершки, мʼята, сік лайму, ром. Серединка: кюлі з малини.', 60, null, null, '40-45 г', null, null, false, null, '/menu/45cc7e7ac1de.jpg', 3),
  ('6ab3ffa0-30f0-4f62-b169-32297df9231e', '62180cd2-9750-466e-a404-64429dc54a69', 'Фісташка — чорниця', 'Білий шоколад, вершки, фісташкова паста. Серединка: кюлі з малини.', 60, null, null, '40-45 г', null, null, false, null, '/menu/19d8bf2d035b.jpg', 4),
  ('a488a9f2-fac6-4e3f-a484-079aae564dcf', '62180cd2-9750-466e-a404-64429dc54a69', 'Ваніль — полуниця', 'Білий шоколад, вершки, натуральна ваніль. Серединка: кюлі з полуниці.', 60, null, null, '40-45 г', null, null, false, null, '/menu/78ca4000052f.jpg', 5),
  ('d6724f41-be22-4489-882c-d036e8837027', 'f5d6909f-624b-412a-9309-ba1080d91f6c', 'Житній', 'Зроблений на житній заквасці, має кислуватий смак та щільну консистенцію.', 51, null, null, '0,450 кг', null, null, false, null, '/menu/4caf1bfe1842.jpg', 0),
  ('2c03a1d5-41e1-404b-961e-f50108591fb3', 'f5d6909f-624b-412a-9309-ba1080d91f6c', 'Мультизерновий', 'Виготовлений на основі пшеничної закваски з додаванням кунжута, соняшникового насіння, льону та суміші пластівців.', 78, null, null, '0,450 кг', null, null, false, null, '/menu/7493bf38f493.jpg', 1),
  ('ab7a4ac7-532c-42bf-a447-e19a48e3259c', 'f5d6909f-624b-412a-9309-ba1080d91f6c', 'Гарбузовий', 'Ніжний і ароматний хліб з додаванням пюре гарбуза. Має солодкуватий смак та мʼяку текстуру.', 73, null, null, '0,450 кг', null, null, false, null, '/menu/94860c6a4d2e.jpg', 2),
